export type FileContext = {
  /** 文件绝对路径（segment.path） */
  path: string
  /** 文件内容（已按行范围提取 + 截断） */
  content: string
  /** 行范围（来自 file segment 的 lineRange，可选） */
  lineRange?: [number, number]
  /** 是否因超限截断（超 50KB 或 500 行） */
  truncated: boolean
  /** 原始字节大小（用于审计/日志） */
  sizeBytes: number
}

export const IMAGE_LIMITS = {
  /** 单图上限（write-session-image IPC 校验，已有逻辑迁移） */
  SINGLE_MAX_BYTES: 20 * 1024 * 1024,
  /** 累积警告阈值（可被 settings.imageAccumulationWarnMB 覆盖） */
  ACCUMULATION_WARN_BYTES_DEFAULT: 15 * 1024 * 1024,
  /** 累积硬上限（可被 settings.imageAccumulationHardMB 覆盖） */
  ACCUMULATION_HARD_BYTES_DEFAULT: 20 * 1024 * 1024,
} as const

export const INLINE_TEXT_MAX_BYTES = 50 * 1024
export const INLINE_TEXT_MAX_LINES = 500
export const INLINE_EXTENSIONS: ReadonlySet<string> = new Set([
  '.ts', '.tsx', '.js', '.jsx', '.vue', '.py', '.rb', '.go', '.rs',
  '.java', '.kt', '.swift', '.c', '.h', '.cpp', '.hpp', '.cs',
  '.md', '.markdown', '.txt', '.json', '.yaml', '.yml', '.toml',
  '.sh', '.bash', '.zsh', '.sql', '.html', '.css', '.scss',
  '.xml', '.svg', '.ini', '.conf', '.env', '.gitignore',
])

// packages/renderer/src/stores/settings.ts 新增
imageAccumulationWarnMB: number  // 默认 15，用户可配
imageAccumulationHardMB: number  // 默认 20，用户可配

// 读取时合并默认值（settings 未配用 IMAGE_LIMITS 常量）
const warnBytes = (settings.imageAccumulationWarnMB ?? IMAGE_LIMITS.ACCUMULATION_WARN_BYTES_DEFAULT / 1024 / 1024) * 1024 * 1024
const hardBytes = (settings.imageAccumulationHardMB ?? IMAGE_LIMITS.ACCUMULATION_HARD_BYTES_DEFAULT / 1024 / 1024) * 1024 * 1024
